(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const toast = document.getElementById('toast'), panel = document.getElementById('job-panel');
  const peopleList = document.getElementById('people-list');
  let W=0,H=0,dpr=1,last=0,toastTimer,live=false,scene='village',won=false;
  const state={coins:0,hero:{x:0,y:0,hp:5,max:5,dir:1,invuln:0,attack:0},people:[],treeCharges:[3,3,3],treeRespawn:0,campTimer:0,key:false,slimes:[],boss:{x:0,y:0,hp:7,max:7,awake:false,attack:0},hitFlash:0};
  const held={};let pointer=null;const jobs=['Archer','Swordsman','Builder'];
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!state.hero.x){state.hero.x=W*.48;state.hero.y=H*.56}layout()}
  window.addEventListener('resize',resize);new ResizeObserver(resize).observe(canvas);
  function layout(){const top=62,bottom=H-105;state.bounds={top,bottom,left:25,right:W-25};if(scene==='dungeon'&&state.boss.x===0){state.boss.x=W*.5;state.boss.y=top+62} }
  function toastMsg(s){toast.textContent=s;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2100)}
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function text(s,x,y,size,color='#f7edce',align='left',font='700'){ctx.fillStyle=color;ctx.font=`${font} ${size}px "DM Sans", sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(s,x,y)}
  function pill(x,y,w,label,value,icon){rounded(x,y,w,42,12,'#17271fe8','#d0aa6870');text(icon,x+14,y+21,17,'#e5c27e','left','500');text(label,x+37,y+14,9,'#aab49b','left','700');text(value,x+37,y+30,14,'#f8edcf','left','700')}
  function draw(){ctx.clearRect(0,0,W,H);if(scene==='village')drawVillage();else drawDungeon();drawHud();drawControls();if(live)requestAnimationFrame(draw)}
  function grass(){ctx.fillStyle='#567548';ctx.fillRect(0,0,W,H);for(let i=0;i<90;i++){const x=((i*167+31)%997)/997*W,y=((i*283+59)%991)/991*H;ctx.fillStyle=i%3?'#718858':'#3e623d';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x,y,3,1.2,-.4,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
  function tree(x,y,scale,charges){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#3d3023';ctx.fillRect(-6,10,12,24);ctx.fillStyle='#694b31';ctx.fillRect(-3,12,6,20);[[0,-11,24,'#315a39'],[-13,0,17,'#416c42'],[14,1,18,'#3b673c'],[1,3,20,'#527949']].forEach(([a,b,r,c])=>{ctx.beginPath();ctx.arc(a,b,r,0,Math.PI*2);ctx.fillStyle=c;ctx.fill();ctx.beginPath();ctx.arc(a-5,b-6,r*.57,0,Math.PI*2);ctx.fillStyle='#729154';ctx.globalAlpha=.52;ctx.fill();ctx.globalAlpha=1});ctx.beginPath();ctx.ellipse(0,27,19,5,0,0,Math.PI*2);ctx.fillStyle='#2e512f';ctx.fill();if(charges>0){ctx.fillStyle='#e7bb55';ctx.beginPath();ctx.arc(12,-18,3.5,0,7);ctx.fill()}ctx.restore()}
  function campfire(x,y){ctx.fillStyle='#5e4930';[[x-13,y+9],[x+13,y+9]].forEach(([a,b])=>{ctx.save();ctx.translate(a,b);ctx.rotate(-.25);rounded(-3,-14,6,29,3,'#765431');ctx.restore()});ctx.beginPath();ctx.ellipse(x,y+5,23,10,0,0,7);ctx.fillStyle='#544333';ctx.fill();ctx.fillStyle='#f07f3e';ctx.beginPath();ctx.moveTo(x,y-20);ctx.quadraticCurveTo(x+14,y-4,x,y+3);ctx.quadraticCurveTo(x-15,y-4,x,y-20);ctx.fill();ctx.fillStyle='#ffd16a';ctx.beginPath();ctx.moveTo(x,y-12);ctx.quadraticCurveTo(x+8,y-2,x,y+2);ctx.quadraticCurveTo(x-7,y-2,x,y-12);ctx.fill();ctx.globalAlpha=.18;ctx.fillStyle='#ffcb6c';ctx.beginPath();ctx.arc(x,y-7,37,0,7);ctx.fill();ctx.globalAlpha=1}
  function cabin(x,y,w=90){rounded(x-w/2,y-14,w,52,5,'#72503a','#392e25');ctx.fillStyle='#8c5c37';ctx.beginPath();ctx.moveTo(x-w/2-9,y-12);ctx.lineTo(x,y-50);ctx.lineTo(x+w/2+9,y-12);ctx.closePath();ctx.fill();ctx.strokeStyle='#c3975c';ctx.lineWidth=2;ctx.stroke();rounded(x-9,y+8,18,30,3,'#392b22');rounded(x+22,y-2,14,13,2,'#d5a657');ctx.globalAlpha=.2;ctx.fillStyle='#fff0bb';ctx.fillRect(x+24,y,10,9);ctx.globalAlpha=1}
  function person(x,y,type='villager',col='#8ba477',scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#273225';ctx.beginPath();ctx.ellipse(0,12,11,5,0,0,7);ctx.fill();ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(-10,-2);ctx.lineTo(-8,12);ctx.lineTo(8,12);ctx.lineTo(10,-2);ctx.quadraticCurveTo(0,-9,-10,-2);ctx.fill();ctx.fillStyle='#dfb887';ctx.beginPath();ctx.arc(0,-9,7,0,7);ctx.fill();ctx.fillStyle=type==='hero'?'#d7c08d':'#5b4938';ctx.beginPath();ctx.arc(0,-11,7,Math.PI,Math.PI*2);ctx.lineTo(7,-8);ctx.lineTo(-7,-8);ctx.fill();if(type==='hero'){ctx.fillStyle='#d5ad63';ctx.fillRect(8,-2,3,15)}ctx.restore()}
  function drawVillage(){grass();const b=state.bounds,top=b.top,bot=b.bottom;
    // winding path and village edge
    ctx.fillStyle='#b49a67';ctx.beginPath();ctx.moveTo(W*.42,top+15);ctx.quadraticCurveTo(W*.38,(top+bot)*.55,W*.55,bot);ctx.lineTo(W*.72,bot);ctx.quadraticCurveTo(W*.58,(top+bot)*.58,W*.57,top+15);ctx.closePath();ctx.fill();ctx.globalAlpha=.18;ctx.fillStyle='#594a36';ctx.fill();ctx.globalAlpha=1;
    ctx.fillStyle='#253b2b';ctx.fillRect(0,top,W,8);ctx.fillStyle='#77905a';ctx.fillRect(0,top+8,W,3);
    // buildings & scenery
    const treePts=[[.13,.31],[.27,.55],[.84,.31],[.86,.58],[.12,.66]];treePts.forEach((p,i)=>tree(W*p[0],top+(bot-top)*p[1],i===0?1.05:.83,state.treeCharges[i%3]));
    cabin(W*.51,top+(bot-top)*.34,Math.min(112,W*.28));
    // bounty board
    rounded(W*.79,top+23,48,38,3,'#674a32','#d5ad6a');ctx.fillStyle='#dab66f';ctx.fillRect(W*.79+8,top+30,32,2);ctx.fillRect(W*.79+8,top+38,23,2);ctx.fillRect(W*.79+8,top+46,27,2);
    campfire(W*.72,top+(bot-top)*.57);ctx.fillStyle='#88643e';ctx.beginPath();ctx.ellipse(W*.72,top+(bot-top)*.57+15,53,25,0,0,7);ctx.fill(); // fire backdrop
    campfire(W*.72,top+(bot-top)*.57);
    // little tents
    tent(W*.62,top+(bot-top)*.57,1);tent(W*.82,top+(bot-top)*.57,.82);
    // gate to dungeon
    const gx=W*.5,gy=top+12;rounded(gx-32,gy-3,64,43,4,'#42372b','#c79e5c');ctx.fillStyle='#282c24';ctx.fillRect(gx-21,gy+4,42,32);for(let i=-1;i<=1;i++)ctx.fillRect(gx+i*13-2,gy+3,4,34);ctx.fillStyle='#c39a5d';ctx.fillRect(gx-33,gy-4,66,5);
    // people discovered at camp
    state.people.forEach((p,i)=>{if(p.found)person(W*.72+(i%2?14:-13),top+(bot-top)*.57+38+Math.floor(i/2)*15,'villager',['#a18c73','#7f9879','#9b786e'][i%3],.8)});
    person(state.hero.x,state.hero.y,'hero','#536d8c',1);drawPrompt(W*.72,top+(bot-top)*.57-37,state.people.length<3?'TAP CAMP · WELCOME A TRAVELER':'YOUR GUILD');
    drawPrompt(W*.13,top+(bot-top)*.31-37,'TAP TREES · OLD COINS');
    drawPrompt(W*.5,top+54,state.coins>=6?'ENTER THE RUIN':'RUIN · 6 COINS');
  }
  function tent(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#9b7750';ctx.beginPath();ctx.moveTo(-24,10);ctx.lineTo(-14,-16);ctx.lineTo(17,-16);ctx.lineTo(27,10);ctx.closePath();ctx.fill();ctx.fillStyle='#664b35';ctx.beginPath();ctx.moveTo(-2,10);ctx.lineTo(-2,-12);ctx.lineTo(13,10);ctx.closePath();ctx.fill();ctx.strokeStyle='#cfb27a';ctx.lineWidth=2;ctx.stroke();ctx.restore()}
  function drawPrompt(x,y,label){rounded(x-59,y-10,118,20,7,'#1b2c22d9','#e2c48265');text(label,x,y,8,'#f0d99c','center','700')}
  function drawDungeon(){ctx.fillStyle='#302e2a';ctx.fillRect(0,0,W,H);const b=state.bounds,top=b.top+7,bot=b.bottom-5,left=13,right=W-13;
    // stone walls and tiled floor
    ctx.fillStyle='#76664b';ctx.fillRect(left,top,right-left,bot-top);ctx.fillStyle='#514a3c';ctx.fillRect(left+9,top+28,right-left-18,bot-top-38);
    const tw=Math.max(42,Math.min(64,(right-left)/8)),th=38;for(let y=top+31,row=0;y<bot-8;y+=th,row++){for(let x=left+12+(row%2)*tw/2;x<right-8;x+=tw){ctx.strokeStyle='#8f8061';ctx.lineWidth=1;ctx.strokeRect(x,y,tw,th);ctx.fillStyle='#d5bc83';ctx.globalAlpha=.06;ctx.fillRect(x+4,y+4,tw-8,th-8)}}ctx.globalAlpha=1;
    // wall torches
    [left+25,W*.5,right-25].forEach(x=>{ctx.fillStyle='#49372b';ctx.fillRect(x-4,top+13,8,18);ctx.fillStyle='#f49b4d';ctx.beginPath();ctx.arc(x,top+12,5,0,7);ctx.fill();ctx.fillStyle='#ffda7c';ctx.beginPath();ctx.arc(x,top+11,2,0,7);ctx.fill()});
    // sealed door
    rounded(W*.5-32,top-5,64,48,5,'#3b3329','#c9a363');text(state.key?'OPEN':'LOCKED',W*.5,top+19,8,'#edce8f','center','700');
    // boss dragon
    drawDragon(state.boss.x,state.boss.y,state.boss.hp/state.boss.max,state.key);
    if(!state.key){drawKey(W*.27,top+(bot-top)*.58);drawPrompt(W*.27,top+(bot-top)*.58+30,'THE OLD KEY')}
    state.slimes.forEach(e=>{if(e.hp>0)drawSlime(e.x,e.y)});
    person(state.hero.x,state.hero.y,'hero','#536d8c',1);
    if(state.boss.hp<=0){rounded(W*.5-91,top+85,182,32,10,'#203d2c','#e6cb81');text('THE RUIN IS CLEARED',W*.5,top+101,12,'#f5e6bf','center','700')}
    if(!state.key)drawPrompt(W*.27,top+(bot-top)*.58+54,'FIND THE KEY FIRST');
  }
  function drawKey(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(-.35);ctx.strokeStyle='#f3cb68';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,-7,9,0,7);ctx.stroke();ctx.fillRect(-2,1,5,21);ctx.fillRect(1,14,9,4);ctx.fillRect(1,20,7,4);ctx.restore();ctx.globalAlpha=.22;ctx.fillStyle='#ffe18a';ctx.beginPath();ctx.arc(x,y,24,0,7);ctx.fill();ctx.globalAlpha=1}
  function drawDragon(x,y,hp,key){ctx.save();ctx.translate(x,y);ctx.fillStyle='#26221d';ctx.beginPath();ctx.ellipse(0,13,46,22,0,0,7);ctx.fill();ctx.fillStyle=key?'#b34e37':'#58634d';ctx.beginPath();ctx.ellipse(0,0,36,23,0,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(-20,-8);ctx.lineTo(-40,-31);ctx.lineTo(-34,0);ctx.lineTo(-21,6);ctx.fill();ctx.beginPath();ctx.moveTo(20,-8);ctx.lineTo(40,-31);ctx.lineTo(34,0);ctx.lineTo(21,6);ctx.fill();ctx.fillStyle='#d6b66e';ctx.beginPath();ctx.arc(-9,-3,3,0,7);ctx.arc(9,-3,3,0,7);ctx.fill();ctx.fillStyle='#e5c48a';ctx.beginPath();ctx.moveTo(-12,17);ctx.lineTo(-8,26);ctx.lineTo(-5,17);ctx.moveTo(7,17);ctx.lineTo(10,26);ctx.lineTo(13,17);ctx.fill();if(!key){ctx.fillStyle='#8e2f2c';ctx.beginPath();ctx.arc(0,-2,3,0,7);ctx.fill()}ctx.restore();
    if(key&&hp>0){rounded(x-45,y-44,90,8,4,'#322b25','#aa9160');rounded(x-43,y-42,86*hp,4,2,'#d1543b');text('RUIN WARDEN',x,y-53,8,'#ead9b4','center','700')}else if(!key)text('SEALED · FIND THE KEY',x,y-43,8,'#b3a78a','center','700')}
  function drawSlime(x,y){ctx.fillStyle='#292b24';ctx.beginPath();ctx.ellipse(x,y+10,18,6,0,0,7);ctx.fill();ctx.fillStyle='#769b57';ctx.beginPath();ctx.moveTo(x-16,y+7);ctx.quadraticCurveTo(x-16,y-15,x,y-17);ctx.quadraticCurveTo(x+18,y-15,x+16,y+7);ctx.closePath();ctx.fill();ctx.fillStyle='#263026';ctx.fillRect(x-6,y-5,3,4);ctx.fillRect(x+5,y-5,3,4)}
  function drawHud(){const y=12;rounded(10,y,W-20,42,13,'#17271fe8','#d0aa6860');text('✦',28,y+21,19,'#ddb66d','center','600');text('HEARTHVALE',45,y+14,9,'#dac28e','left','700');text(scene==='village'?'VILLAGE':'THE OLD RUIN',45,y+29,9,'#9dac92','left','600');
    const coinW=82;pill(W-103,y,92,'OLD COINS',String(state.coins),'◉');
    if(scene==='dungeon'){rounded(113,y+8,91,26,8,'#22352a','#8e805e');text(state.key?'✦ KEY':'○ KEY',158,y+21,10,state.key?'#f4cb69':'#bcb8a4','center','700');rounded(W-203,y+8,90,26,8,'#3c2925','#9d5140');text('♥ '.repeat(state.hero.hp)+'♡ '.repeat(state.hero.max-state.hero.hp),W-158,y+21,10,'#ed8771','center','700')}
    if(scene==='village'){const aw=48;rounded(W-161,y+8,49,26,8,'#22352a','#8e805e');text('👥 '+state.people.length,W-137,y+21,10,'#e7d8b8','center','700');rounded(W-106,y+8,94,26,8,'#344430','#b2a46e');text('JOBS  ↗',W-59,y+21,10,'#f2dfad','center','700')}
  }
  function drawControls(){const y=H-57;ctx.globalAlpha=.85;
    // dpad cluster
    control(W*.16,y,'↑','up');control(W*.16-43,y+30,'←','left');control(W*.16+43,y+30,'→','right');control(W*.16,y+60,'↓','down');
    const ax=W-117;control(ax,y+16,'⚔','attack',true);control(W-46,y+42,'✦','interact',true);ctx.globalAlpha=1;
    text('MOVE',W*.16,y+91,8,'#c6c6a9','center','700');text(scene==='village'?'TAP TO GATHER':'TAP TO STRIKE',W-84,y+91,8,'#c6c6a9','center','700');
  }
  function control(x,y,label,action,large=false){const r=large?25:20;ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fillStyle=pointer?.action===action?'#be9858':'#17251fcc';ctx.fill();ctx.strokeStyle=large?'#d5b273':'#d7c69a88';ctx.lineWidth=1.5;ctx.stroke();text(label,x,y+(label==='↑'?-1:0),large?20:14,'#f2e4bf','center','700')}

