(() => {
  const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),toast=document.getElementById('toast'),panel=document.getElementById('job-panel'),peopleList=document.getElementById('people-list');
  let W=0,H=0,dpr=1,live=false,scene='village',toastTimer;const held={};let pointer=null;
  const state={coins:0,hero:{x:0,y:0,hp:5,max:5,dir:1,invuln:0,attack:0},people:[],treeCharges:[3,3,3],treeRespawn:0,campTimer:0,key:false,slimes:[],boss:{x:0,y:0,hp:7,max:7,awake:false,attack:0},archerTick:0,won:false};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!state.hero.x){state.hero.x=W*.48;state.hero.y=H*.56}layout()}
  function layout(){state.bounds={top:62,bottom:H-105,left:25,right:W-25};if(scene==='dungeon'&&state.boss.x===0){state.boss.x=W*.5;state.boss.y=state.bounds.top+62}}
  window.addEventListener('resize',resize);new ResizeObserver(resize).observe(canvas);
  function toastMsg(s){toast.textContent=s;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2100)}
  function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function text(s,x,y,size,color='#f7edce',align='left',font='700'){ctx.fillStyle=color;ctx.font=`${font} ${size}px "DM Sans", sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(s,x,y)}
  function pill(x,y,w,label,value,icon){rounded(x,y,w,42,12,'#17271fe8','#d0aa6870');text(icon,x+14,y+21,17,'#e5c27e','left','500');text(label,x+37,y+14,9,'#aab49b','left','700');text(value,x+37,y+30,14,'#f8edcf','left','700')}
  function draw(){ctx.clearRect(0,0,W,H);if(scene==='village')drawVillage();else drawDungeon();drawHud();drawControls();if(live)requestAnimationFrame(draw)}
  function grass(){ctx.fillStyle='#567548';ctx.fillRect(0,0,W,H);for(let i=0;i<90;i++){const x=((i*167+31)%997)/997*W,y=((i*283+59)%991)/991*H;ctx.fillStyle=i%3?'#718858':'#3e623d';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x,y,3,1.2,-.4,0,7);ctx.fill()}ctx.globalAlpha=1}
