  function campfire(x,y){ctx.fillStyle='#5e4930';[[x-13,y+9],[x+13,y+9]].forEach(([a,b])=>{ctx.save();ctx.translate(a,b);ctx.rotate(-.25);rounded(-3,-14,6,29,3,'#765431');ctx.restore()});ctx.beginPath();ctx.ellipse(x,y+5,23,10,0,0,7);ctx.fillStyle='#544333';ctx.fill();ctx.fillStyle='#f07f3e';ctx.beginPath();ctx.moveTo(x,y-20);ctx.quadraticCurveTo(x+14,y-4,x,y+3);ctx.quadraticCurveTo(x-15,y-4,x,y-20);ctx.fill();ctx.fillStyle='#ffd16a';ctx.beginPath();ctx.moveTo(x,y-12);ctx.quadraticCurveTo(x+8,y-2,x,y+2);ctx.quadraticCurveTo(x-7,y-2,x,y-12);ctx.fill();ctx.globalAlpha=.18;ctx.fillStyle='#ffcb6c';ctx.beginPath();ctx.arc(x,y-7,37,0,7);ctx.fill();ctx.globalAlpha=1}
