  function person(x,y,type='villager',col='#8ba477',scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#273225';ctx.beginPath();ctx.ellipse(0,12,11,5,0,0,7);ctx.fill();ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(-10,-2);ctx.lineTo(-8,12);ctx.lineTo(8,12);ctx.lineTo(10,-2);ctx.quadraticCurveTo(0,-9,-10,-2);ctx.fill();ctx.fillStyle='#dfb887';ctx.beginPath();ctx.arc(0,-9,7,0,7);ctx.fill();ctx.fillStyle=type==='hero'?'#d7c08d':'#5b4938';ctx.beginPath();ctx.arc(0,-11,7,Math.PI,7);ctx.lineTo(7,-8);ctx.lineTo(-7,-8);ctx.fill();if(type==='hero'){ctx.fillStyle='#d5ad63';ctx.fillRect(8,-2,3,15)}ctx.restore()}
