    state.people.forEach((p,i)=>person(W*.72+(i%2?14:-13),top+(bot-top)*.57+38+Math.floor(i/2)*15,'villager',['#a18c73','#7f9879','#9b786e'][i%3],.8));person(state.hero.x,state.hero.y,'hero','#536d8c',1);
