  }
  function tent(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#9b7750';ctx.beginPath();ctx.moveTo(-24,10);ctx.lineTo(-14,-16);ctx.lineTo(17,-16);ctx.lineTo(27,10);ctx.closePath();ctx.fill();ctx.fillStyle='#664b35';ctx.beginPath();ctx.moveTo(-2,10);ctx.lineTo(-2,-12);ctx.lineTo(13,10);ctx.closePath();ctx.fill();ctx.strokeStyle='#cfb27a';ctx.lineWidth=2;ctx.stroke();ctx.restore()}
  function drawPrompt(x,y,label){rounded(x-59,y-10,118,20,7,'#1b2c22d9','#e2c48265');text(label,x,y,8,'#f0d99c','center','700')}
  function drawDungeon(){ctx.fillStyle='#302e2a';ctx.fillRect(0,0,W,H);const b=state.bounds,top=b.top+7,bot=b.bottom-5,left=13,right=W-13;ctx.fillStyle='#76664b';ctx.fillRect(left,top,right-left,bot-top);ctx.fillStyle='#514a3c';ctx.fillRect(left+9,top+28,right-left-18,bot-top-38);
    const tw=Math.max(42,Math.min(64,(right-left)/8)),th=38;for(let y=top+31,row=0;y<bot-8;y+=th,row++)for(let x=left+12+(row%2)*tw/2;x<right-8;x+=tw){ctx.strokeStyle='#8f8061';ctx.lineWidth=1;ctx.strokeRect(x,y,tw,th);ctx.fillStyle='#d5bc83';ctx.globalAlpha=.06;ctx.fillRect(x+4,y+4,tw-8,th-8)}ctx.globalAlpha=1;
    [left+25,W*.5,right-25].forEach(x=>{ctx.fillStyle='#49372b';ctx.fillRect(x-4,top+13,8,18);ctx.fillStyle='#f49b4d';ctx.beginPath();ctx.arc(x,top+12,5,0,7);ctx.fill();ctx.fillStyle='#ffda7c';ctx.beginPath();ctx.arc(x,top+11,2,0,7);ctx.fill()});rounded(W*.5-32,top-5,64,48,5,'#3b3329','#c9a363');text(state.key?'OPEN':'LOCKED',W*.5,top+19,8,'#edce8f','center','700');
    drawDragon(state.boss.x,state.boss.y,state.boss.hp/state.boss.max,state.key);if(!state.key){drawKey(W*.27,top+(bot-top)*.58);drawPrompt(W*.27,top+(bot-top)*.58+30,'THE OLD KEY')}state.slimes.forEach(e=>{if(e.hp>0)drawSlime(e.x,e.y)});person(state.hero.x,state.hero.y,'hero','#536d8c',1);if(state.boss.hp<=0){rounded(W*.5-91,top+85,182,32,10,'#203d2c','#e6cb81');text('THE RUIN IS CLEARED',W*.5,top+101,12,'#f5e6bf','center','700')}if(!state.key)drawPrompt(W*.27,top+(bot-top)*.58+54,'FIND THE KEY FIRST')
  }
  function drawKey(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(-.35);ctx.strokeStyle='#f3cb68';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,-7,9,0,7);ctx.stroke();ctx.fillRect(-2,1,5,21);ctx.fillRect(1,14,9,4);ctx.fillRect(1,20,7,4);ctx.restore();ctx.globalAlpha=.22;ctx.fillStyle='#ffe18a';ctx.beginPath();ctx.arc(x,y,24,0,7);ctx.fill();ctx.globalAlpha=1}
  function drawDragon(x,y,hp,key){ctx.save();ctx.translate(x,y);ctx.fillStyle='#26221d';ctx.beginPath();ctx.ellipse(0,13,46,22,0,0,7);ctx.fill();ctx.fillStyle=key?'#b34e37':'#58634d';ctx.beginPath();ctx.ellipse(0,0,36,23,0,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(-20,-8);ctx.lineTo(-40,-31);ctx.lineTo(-34,0);ctx.lineTo(-21,6);ctx.fill();ctx.beginPath();ctx.moveTo(20,-8);ctx.lineTo(40,-31);ctx.lineTo(34,0);ctx.lineTo(21,6);ctx.fill();ctx.fillStyle='#d6b66e';ctx.beginPath();ctx.arc(-9,-3,3,0,7);ctx.arc(9,-3,3,0,7);ctx.fill();ctx.fillStyle='#e5c48a';ctx.beginPath();ctx.moveTo(-12,17);ctx.lineTo(-8,26);ctx.lineTo(-5,17);ctx.moveTo(7,17);ctx.lineTo(10,26);ctx.lineTo(13,17);ctx.fill();if(!key){ctx.fillStyle='#8e2f2c';ctx.beginPath();ctx.arc(0,-2,3,0,7);ctx.fill()}ctx.restore();if(key&&hp>0){rounded(x-45,y-44,90,8,4,'#322b25','#aa9160');rounded(x-43,y-42,86*hp,4,2,'#d1543b');text('RUIN WARDEN',x,y-53,8,'#ead9b4','center','700')}else if(!key)text('SEALED · FIND THE KEY',x,y-43,8,'#b3a78a','center','700')}
  function drawSlime(x,y){ctx.fillStyle='#292b24';ctx.beginPath();ctx.ellipse(x,y+10,18,6,0,0,7);ctx.fill();ctx.fillStyle='#769b57';ctx.beginPath();ctx.moveTo(x-16,y+7);ctx.quadraticCurveTo(x-16,y-15,x,y-17);ctx.quadraticCurveTo(x+18,y-15,x+16,y+7);ctx.closePath();ctx.fill();ctx.fillStyle='#263026';ctx.fillRect(x-6,y-5,3,4);ctx.fillRect(x+5,y-5,3,4)}
  function drawHud(){const y=12;rounded(10,y,W-20,42,13,'#17271fe8','#d0aa6860');text('✦',28,y+21,19,'#ddb66d','center','600');text('HEARTHVALE',45,y+14,9,'#dac28e','left','700');text(scene==='village'?'VILLAGE':'THE OLD RUIN',45,y+29,9,'#9dac92','left','600');pill(W-103,y,92,'OLD COINS',String(state.coins),'◉');if(scene==='dungeon'){rounded(113,y+8,91,26,8,'#22352a','#8e805e');text(state.key?'✦ KEY':'○ KEY',158,y+21,10,state.key?'#f4cb69':'#bcb8a4','center','700');rounded(W-203,y+8,90,26,8,'#3c2925','#9d5140');text('♥ '.repeat(state.hero.hp)+'♡ '.repeat(state.hero.max-state.hero.hp),W-158,y+21,10,'#ed8771','center','700')}else{rounded(W-161,y+8,49,26,8,'#22352a','#8e805e');text('👥 '+state.people.length,W-137,y+21,10,'#e7d8b8','center','700');rounded(W-106,y+8,94,26,8,'#344430','#b2a46e');text('JOBS  ↗',W-59,y+21,10,'#f2dfad','center','700')}}
