function drawControls(){const y=H-105;ctx.globalAlpha=.85;control(W*.16,y,'↑','up');control(W*.16-43,y+30,'←','left');control(W*.16+43,y+30,'→','right');control(W*.16,y+60,'↓','down');control(W-117,y+16,'⚔','attack',true);control(W-46,y+42,'✦','interact',true);ctx.globalAlpha=1;text('MOVE',W*.16,H-14,8,'#c6c6a9','center','700');text(scene==='village'?'TAP TO GATHER':'TAP TO STRIKE',W-84,H-14,8,'#c6c6a9','center','700')}
function update(dt){if(!live)return;const h=state.hero,b=state.bounds;h.attack=Math.max(0,h.attack-dt);h.invuln=Math.max(0,h.invuln-dt);let dx=(held.right?1:0)-(held.left?1:0),dy=(held.down?1:0)-(held.up?1:0);if(dx||dy){const n=Math.hypot(dx,dy);h.x+=dx/n*145*dt;h.y+=dy/n*145*dt;if(dx)h.dir=dx>0?1:-1}h.x=clamp(h.x,b.left+17,b.right-17);h.y=clamp(h.y,b.top+62,b.bottom-10);
  if(scene==='village'){if(state.treeRespawn>0){state.treeRespawn-=dt;if(state.treeRespawn<=0)state.treeCharges=[3,3,3]}if(state.campTimer>0)state.campTimer-=dt}
  else updateDungeon(dt);if(h.hp<=0){h.hp=h.max;h.x=W*.5;h.y=H*.65;scene='village';toastMsg('Your companions carried you to safety. Try again!');state.key=false;state.slimes=[]}}
function updateDungeon(dt){const h=state.hero,b=state.bounds,top=b.top+10,bot=b.bottom-13;h.x=clamp(h.x,30,W-30);h.y=clamp(h.y,top+42,bot-12);const keyX=W*.27,keyY=top+(bot-top)*.58;if(!state.key&&Math.hypot(h.x-keyX,h.y-keyY)<34){state.key=true;state.boss.awake=true;toastMsg('The old key hums. The warden stirs!')}
  state.slimes.forEach(e=>{if(e.hp<=0)return;const d=Math.hypot(h.x-e.x,h.y-e.y);if(d>25){e.x+=(h.x-e.x)/d*28*dt;e.y+=(h.y-e.y)/d*28*dt}e.cool-=dt;if(d<29&&e.cool<=0){damageHero(1);e.cool=1.6}});
  const boss=state.boss;if(state.key&&boss.hp>0){boss.attack-=dt;const d=Math.hypot(h.x-boss.x,h.y-boss.y);if(d<55&&boss.attack<=0){damageHero(1);boss.attack=1.8}}
  state.archerTick-=dt;if(state.archerTick<=0){const archers=state.people.filter(p=>p.job==='Archer').length;if(archers){const target=state.slimes.find(e=>e.hp>0)||((state.key&&boss.hp>0)?boss:null);if(target){target.hp=Math.max(0,target.hp-(target===boss?0.65:1));if(target===boss&&target.hp===0)victory()}state.archerTick=1.4}else state.archerTick=.3}
  if(state.boss.hp<=0)victory()}
function damageHero(n){const h=state.hero;if(h.invuln>0)return;h.hp-=n;h.invuln=1.05;document.body.style.filter='brightness(1.35)';setTimeout(()=>document.body.style.filter='',100);if(h.hp<=0)toastMsg('The ruin sends you back to camp…')}
function attack(){if(!live||scene!=='dungeon'||state.hero.attack>0)return;state.hero.attack=.42;const h=state.hero;if(!state.key){toastMsg('The warden is sealed. Find the old key!');return}let target=null,dist=83;for(const e of state.slimes){if(e.hp<=0)continue;const d=Math.hypot(e.x-h.x,e.y-h.y);if(d<dist){dist=d;target=e}}const d=Math.hypot(state.boss.x-h.x,state.boss.y-h.y);if(state.boss.hp>0&&d<dist){target=state.boss;dist=d}if(target){const sword=state.people.filter(p=>p.job==='Swordsman').length;target.hp=Math.max(0,target.hp-(target===state.boss?1+sword*.35:2+sword));if(target===state.boss&&target.hp<=0)victory()}else toastMsg('Move close to a creature to strike.')}
function victory(){if(state.won)return;state.won=true;state.boss.hp=0;setTimeout(()=>document.getElementById('win-screen').classList.remove('hidden'),650)}
function enterDungeon(){if(state.coins<6){toastMsg(`The ruin needs 6 old coins. You have ${state.coins}.`);return}scene='dungeon';state.key=false;state.boss={x:W*.5,y:state.bounds.top+70,hp:7,max:7,awake:false,attack:0};state.slimes=[{x:W*.32,y:H*.48,hp:3,cool:1},{x:W*.68,y:H*.55,hp:3,cool:1.6}];state.hero.x=W*.5;state.hero.y=state.bounds.top+state.bounds.bottom*.0+90;state.hero.hp=state.hero.max;layout();toastMsg('Find the key. Then defeat the ruin warden!')}
function discoverTree(x,y){const top=state.bounds.top,bot=state.bounds.bottom,pts=[[.13,.31],[.27,.55],[.84,.31],[.86,.58],[.12,.66]];for(let i=0;i<pts.length;i++){const tx=W*pts[i][0],ty=top+(bot-top)*pts[i][1];if(Math.hypot(x-tx,y-ty)<38){const index=i%3;if(state.treeCharges[index]>0){state.treeCharges[index]--;state.coins++;toastMsg('+1 old coin · '+state.coins+' gathered');if(state.treeCharges.every(n=>n===0))state.treeRespawn=12}else toastMsg('That tree is bare. Try another!');return true}}return false}
function visitCamp(){if(state.people.length>=3){openJobs();toastMsg('Your guild is ready for the ruin.');return}if(state.campTimer>0){toastMsg('The fire is warm. A traveler may arrive soon.');return}const names=['Mira','Rowan','Tamsin'];state.people.push({name:names[state.people.length],job:'Builder'});state.campTimer=1.2;toastMsg(`${names[state.people.length-1]} found a place by the fire.`);renderPeople();if(state.people.length===1)setTimeout(openJobs,550)}

