const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 420, height: 820 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.click('#start-button');
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'screenshots/village.jpg', type: 'jpeg', quality: 80 });
  // tap trees
  const trees = [[0.13, .31], [.27, .55], [.84, .31], [.86, .58], [.12, .66]];
  for (const [fx, fy] of trees) {
    const box = await page.locator('#game').boundingBox();
    const top = 62, bot = box.height - 105;
    await page.mouse.click(box.x + box.width * fx, box.y + top + (bot - top) * fy);
    await page.waitForTimeout(150);
  }
  await page.waitForTimeout(300);
  await page.screenshot({ path: 'screenshots/coins.jpg', type: 'jpeg', quality: 80 });
  // camp tap
  const box = await page.locator('#game').boundingBox();
  await page.mouse.click(box.x + box.width * .72, box.y + 62 + (box.height - 167) * .57);
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/jobs.jpg', type: 'jpeg', quality: 80 });
  console.log('errors', errors);
  console.log('text', await page.evaluate(() => document.getElementById('people-list').innerText));
  await browser.close();
})();

