const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  for (const [w, h, name] of [[960, 720, 'landscape'], [768, 1024, 'tablet']]) {
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    const errors = [];
    page.on('pageerror', e => errors.push(String(e)));
    await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
    await page.click('#start-button');
    await page.waitForTimeout(2600);
    await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 82 });
    const box = await page.locator('#game').boundingBox();
    const W = box.width, H = box.height, top = 92, bot = H - 118;
    const click = (x, y) => page.mouse.click(box.x + x, box.y + y);
    const trees = [[.11, .26], [.29, .51], [.89, .27], [.10, .68]];
    for (let r = 0; r < 2; r++) for (const [fx, fy] of trees) { await click(W * fx, top + (bot - top) * fy); await page.waitForTimeout(90); }
    await click(W * .73, top + (bot - top) * .64);
    await page.waitForTimeout(800);
    await page.screenshot({ path: `screenshots/${name}-jobs.jpg`, type: 'jpeg', quality: 82 });
    await page.keyboard.press('Escape');
    await page.waitForTimeout(250);
    await page.screenshot({ path: `screenshots/${name}-coins.jpg`, type: 'jpeg', quality: 82 });
    console.log(name, 'errors', errors);
    await page.close();
  }
  await browser.close();
})();

