    await click(W * .73, top + (bot - top) * .68);
    await page.waitForTimeout(700);
    if (i < 2) await page.keyboard.press('Escape');
    await page.waitForTimeout(250);
  }
  // assign jobs: archer, swordsman, builder
  const selects = page.locator('#people-list select');
  await selects.nth(0).selectOption('Archer');
  await selects.nth(1).selectOption('Swordsman');
  await selects.nth(2).selectOption('Builder');
  await page.waitForTimeout(300);
