const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 420, height: 820 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.click('#start-button');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: 'screenshots/village.jpg', type: 'jpeg', quality: 82 });

  const box = await page.locator('#game').boundingBox();
  const W = box.width, H = box.height;
  const top = 92, bot = H - 118;
  const span = bot - top;
  const click = (x, y) => page.mouse.click(box.x + x, box.y + y);

  const trees = [[.11, .26], [.22, .55], [.89, .27], [.10, .68]];
  for (let r = 0; r < 2; r++) for (const [fx, fy] of trees) {
    await click(W * fx, top + span * fy);
    await page.waitForTimeout(110);
  }
  await page.waitForTimeout(300);
  await page.screenshot({ path: 'screenshots/coins.jpg', type: 'jpeg', quality: 82 });

  // camp visit -> traveler + job panel
  await click(W * .78, top + span * .68);
  await page.waitForTimeout(900);
  await page.locator('#people-list select').first().selectOption('Archer');
  await page.waitForTimeout(250);
  await page.screenshot({ path: 'screenshots/jobs.jpg', type: 'jpeg', quality: 82 });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(350);

  // gate
  await click(W * .5, top + 75);
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/dungeon.jpg', type: 'jpeg', quality: 82 });

  // key
  const keyX = W * .28;
  const keyY = (top + 10) + ((bot - 14) - (top + 10)) * .58;
  await click(keyX, keyY);
  await page.waitForTimeout(1400);
  await page.screenshot({ path: 'screenshots/key.jpg', type: 'jpeg', quality: 82 });

  // walk up to the warden
  for (let i = 0; i < 10; i++) {
    await click(W * .5, 240);
    await page.waitForTimeout(180);
  }
  // strike until the warden falls
  for (let i = 0; i < 30; i++) {
    await page.mouse.click(box.x + W - 112, box.y + H - 80);
    await page.waitForTimeout(300);
  }
  await page.waitForTimeout(1200);
  await page.screenshot({ path: 'screenshots/boss.jpg', type: 'jpeg', quality: 82 });

  const winVisible = await page.evaluate(() => !document.getElementById('win-screen').classList.contains('hidden'));
  const stats = await page.evaluate(() => document.getElementById('win-stats').textContent);
  console.log('errors', errors);
  console.log('win visible', winVisible);
  console.log('win stats', JSON.stringify(stats));
  await browser.close();
})();

