ctx.fillRect(left + 8, top + 30, right - left - 16, bot - top - 46);
const tw = Math.max(42, Math.min(66, (right - left) / 7.5)), th = 44;
for (let y = top + 32, row = 0; y < bot - 20; y += th, row++) {
  for (let x = left + 10 + (row % 2) * tw / 2; x < right - 12; x += tw) {
    const w = Math.min(tw - 3, right - 10 - x);
    if (w < 8) continue;
    ctx.fillStyle = row % 2 ? '#565043' : '#514b3e';
    ctx.fillRect(x, y, w, th - 3);
    // worn top edge and shadowed bottom edge
    ctx.fillStyle = 'rgba(216,196,154,.13)';
    ctx.fillRect(x + 2, y + 1, w - 4, 2);
    ctx.fillStyle = 'rgba(18,17,13,.26)';
    ctx.fillRect(x + 2, y + th - 6, w - 4, 2);
    ctx.strokeStyle = 'rgba(24,22,17,.32)'; ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, w - 1, th - 4);
    // mottled wear
    ctx.fillStyle = row % 2 ? 'rgba(94,106,72,.07)' : 'rgba(180,166,124,.05)';
    ctx.fillRect(x + 6, y + 7, Math.max(4, w * 0.42), th - 18);
    ctx.fillStyle = 'rgba(28,26,20,.12)';
    ctx.beginPath();
    ctx.ellipse(x + w * 0.68, y + th * 0.62, Math.max(3, w * 0.16), 3, 0.3, 0, 7);
    ctx.fill();
  }
}
// rubble along the lower corners
[[left + 26, bot - 34], [right - 30, bot - 40], [left + 44, bot - 50]].forEach(([rx, ry], i) => {
  for (let k = 0; k < 4; k++) {
    const a = rx + Math.cos(k * 1.9 + i) * (7 + k * 3);
    const bb = ry + Math.sin(k * 2.3 + i) * (3 + k * 2);
    ctx.fillStyle = k % 2 ? '#5b5546' : '#494435';
    ctx.beginPath(); ctx.ellipse(a, bb, 4 + (k % 2) * 2, 2.6, k, 0, 7); ctx.fill();
  }
});

