const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  for (const [w, h, name] of [[320, 568, 'small'], [390, 844, 'phone']]) {
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    const errors = [];
    page.on('pageerror', e => errors.push(String(e)));
    await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
    await page.waitForTimeout(300);
    await page.screenshot({ path: `screenshots/${name}-start.jpg`, type: 'jpeg', quality: 82 });
    await page.click('#start-button');
    await page.waitForTimeout(2600);
    await page.screenshot({ path: `screenshots/${name}-game.jpg`, type: 'jpeg', quality: 82 });
    const box = await page.locator('#game').boundingBox();
    const top = 92, bot = box.height - 118, span = bot - top;
    await page.mouse.click(box.x + box.width * .78, box.y + top + span * .68);
    await page.waitForTimeout(900);
    await page.screenshot({ path: `screenshots/${name}-jobs.jpg`, type: 'jpeg', quality: 82 });
    console.log(name, errors);
    await page.close();
  }
  await browser.close();
})();

