})();

const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.click('#start-button');
  await page.waitForTimeout(500);
  const box = await page.locator('#game').boundingBox();
  const W = box.width, H = box.height, top = 92, bot = H - 118, span = bot - top;
  const click = (x, y) => page.mouse.click(box.x + x, box.y + y);
  const trees = [[.11, .26], [.22, .55], [.89, .27], [.10, .68]];
  for (let r = 0; r < 2; r++) for (const [fx, fy] of trees) { await click(W * fx, top + span * fy); await page.waitForTimeout(80); }
  for (let i = 0; i < 3; i++) {
    await click(W * .78, top + span * .68);
    await page.waitForTimeout(850);
    await page.keyboard.press('Escape');
    await page.waitForTimeout(600);
  }
  await click(W - 40, 32);
  await page.waitForTimeout(400);
  const selects = page.locator('#people-list select');
  const count = await selects.count();
  for (let i = 0; i < count; i++) {
    await selects.nth(i).selectOption(['Archer', 'Swordsman', 'Builder'][i % 3]);
  }
  await page.waitForTimeout(300);
  const roster = await page.evaluate(() => document.getElementById('people-list').innerText);
  await page.keyboard.press('Escape');
  await click(W * .5, top + 75);
  await page.waitForTimeout(800);
  const keyX = W * .28, keyY = (top + 10) + ((bot - 14) - (top + 10)) * .58;
  await click(keyX, keyY);
  await page.waitForTimeout(1000);
  for (let i = 0; i < 10; i++) { await click(W * .5, 250); await page.waitForTimeout(150); }
  for (let i = 0; i < 30; i++) {
    await page.mouse.click(box.x + W - 112, box.y + H - 80);
    await page.waitForTimeout(280);
  }
  await page.waitForTimeout(1200);
  const win = await page.evaluate(() => !document.getElementById('win-screen').classList.contains('hidden'));
  const stats = await page.evaluate(() => document.getElementById('win-stats').textContent);
  const overlays = await page.evaluate(() => ({
    rotate: getComputedStyle(document.getElementById('rotate-screen')).display,
    panel: document.getElementById('job-panel').className,
  }));
  console.log({ errors, count, roster, win, stats, overlays });
  await browser.close();
})();
